import React, { useState, useEffect, useCallback } from 'react';
import { fetchTrades } from '../services/api';

export default function TransactionsPage() {
  const [trades,  setTrades]  = useState([]);
  const [page,    setPage]    = useState(1);
  const [search,  setSearch]  = useState('');
  const [loading, setLoading] = useState(true);

  const load = useCallback((p) => {
    setLoading(true);
    fetchTrades(p)
      .then(d => { setTrades(Array.isArray(d) ? d : []); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  useEffect(() => { load(page); }, [page, load]);

  const filtered = trades.filter(t =>
    !search ||
    t.symbol?.toLowerCase().includes(search.toLowerCase()) ||
    t.seller_name?.toLowerCase().includes(search.toLowerCase()) ||
    t.buyer_name?.toLowerCase().includes(search.toLowerCase())
  );

  const riskBadge = (s) => {
    if (!s) return null;
    if (s >= 70) return <span className="badge badge-high">HIGH</span>;
    if (s >= 40) return <span className="badge badge-medium">MED</span>;
    return <span className="badge badge-low">LOW</span>;
  };

  return (
    <div style={{ background: '#080808', minHeight: '100vh', padding: 32 }} className="grid-bg">
      <div style={{ maxWidth: 1300, margin: '0 auto' }}>
        <div style={{ marginBottom: 28 }}>
          <h1 style={{ fontSize: 28, fontWeight: 800, letterSpacing: '-0.02em', marginBottom: 8 }}>
            Transaction <span className="neon">Log</span>
          </h1>
          <p style={{ color: '#6b7280', fontSize: 14 }}>Complete trade history with fraud risk indicators</p>
        </div>

        <div style={{ display: 'flex', gap: 12, marginBottom: 20, flexWrap: 'wrap', alignItems: 'center' }}>
          <input className="search-input" placeholder="Filter by stock, seller, buyer..." value={search} onChange={e => setSearch(e.target.value)} style={{ maxWidth: 320 }} />
          <div className="tag">{filtered.length} trades on this page</div>
          <div style={{ marginLeft: 'auto', display: 'flex', gap: 8 }}>
            <button className="btn-outline" disabled={page <= 1} onClick={() => setPage(p => p - 1)} style={{ padding: '8px 16px', fontSize: 13, opacity: page <= 1 ? 0.4 : 1 }}>← Prev</button>
            <span style={{ display: 'flex', alignItems: 'center', padding: '0 12px', color: '#9ca3af', fontSize: 13 }}>Page {page}</span>
            <button className="btn-outline" onClick={() => setPage(p => p + 1)} style={{ padding: '8px 16px', fontSize: 13, opacity: trades.length < 50 ? 0.4 : 1 }} disabled={trades.length < 50}>Next →</button>
          </div>
        </div>

        <div className="glass" style={{ overflow: 'hidden' }}>
          {loading ? (
            <div style={{ padding: 64, textAlign: 'center', color: '#4b5563' }}>
              <div className="neon" style={{ fontSize: 28, marginBottom: 12 }}>⟳</div>
              Loading trades...
            </div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th><th>Stock</th><th>Seller</th><th>Buyer</th>
                    <th>Price</th><th>Qty</th><th>Risk</th><th>Time</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((t, i) => (
                    <tr key={i} style={{ borderLeft: t.risk_score >= 70 ? '2px solid rgba(239,68,68,0.4)' : '2px solid transparent' }}>
                      <td style={{ color: '#4b5563', fontFamily: 'monospace', fontSize: 12 }}>#{t.trade_id}</td>
                      <td><span className="neon" style={{ fontWeight: 700, fontSize: 14 }}>{t.symbol || '—'}</span></td>
                      <td style={{ color: '#d1d5db' }}>{t.seller_name || `T${t.seller_id}`}</td>
                      <td style={{ color: '#d1d5db' }}>{t.buyer_name  || `T${t.buyer_id}`}</td>
                      <td style={{ fontWeight: 600, color: '#fff' }}>${Number(t.price).toFixed(2)}</td>
                      <td style={{ color: '#9ca3af' }}>{t.quantity?.toLocaleString()}</td>
                      <td>{riskBadge(t.risk_score)}</td>
                      <td style={{ color: '#4b5563', fontSize: 11 }}>
                        {t.timestamp ? new Date(t.timestamp).toLocaleString('en-IN', { dateStyle: 'short', timeStyle: 'short' }) : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
